def count_words(s):
    counts = {}
    for w in s.split():
        counts[w] = counts.get(w, 0) + 1
    return counts

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def trace(fn):
    def wrap(*a, **kw):
        print(fn.__name__, a, kw)
        return fn(*a, **kw)
    return wrap

